#!/usr/bin/env bash
# Prints the state run.sh touches, one line per item, so two runs can be diffed.
# Run as the test user inside the container:  ./test/snapshot.sh >/tmp/snap
#
#   /etc and flatpak overrides   content hash (rewriting identical content is fine)
#   $HOME, /usr/local, /opt      mtime + size (catches re-downloads and rebuilds)
#   keys, git, users, packages   command output
set -uo pipefail

# regenerated by package hooks or the container runtime, not by setup
ETC_SKIP='^/etc/(ld\.so\.cache|resolv\.conf|hostname|hosts|mtab|\.pwd\.lock|pacman\.d/gnupg/|ca-certificates/extracted/|ssl/certs/|pki/ca-trust/extracted/)'

section() { printf '\n## %s\n' "$1"; }

section "etc (sha256)"
sudo find /etc /var/lib/flatpak/overrides -xdev -type f -print0 2>/dev/null |
  sudo xargs -0 sha256sum 2>/dev/null | awk '{print $2, $1}' | grep -Ev "$ETC_SKIP" | sort

# caches and the setup checkout itself are expected to change between runs
section "files (mtime size)"
find "$HOME" /usr/local /opt -xdev \
  \( -path "$HOME/.cache" -o -path "$HOME/.npm" -o -path "$HOME/setup" -o -path "$HOME/.gnupg" \
  -o -path "$HOME/.local/state" -o -path "$HOME/.local/share/pnpm/store" -o -path "$HOME/go/pkg" \
  -o -path "$HOME/.cargo/registry" -o -path "$HOME/.rustup/downloads" -o -path "$HOME/.rustup/tmp" \
  -o -path "$HOME/.nvm/.cache" -o -path "$HOME/.config/nvm/.cache" -o -path "$HOME/.local/share/gem/specs" \
  -o -path "$HOME/.julia/logs" -o -path "$HOME/.lesshst" \) -prune \
  -o \( -type f -o -type l \) -printf '%p %T@ %s %l\n' 2>/dev/null | sort

section "gpg secret keys"
gpg --list-secret-keys --with-colons 2>/dev/null | awk -F: '$1 == "fpr" || $1 == "uid" {print $1, $10}'

section "ssh key"
ssh-keygen -lf "$HOME/.ssh/id_ed25519.pub" 2>/dev/null

section "git config"
git config --global --list 2>/dev/null

section "user"
getent passwd "$(id -un)"
id -nG "$(id -un)" | tr ' ' '\n' | sort | tr '\n' ' '
echo

section "packages"
if command -v pacman >/dev/null; then
  pacman -Q
elif command -v dpkg-query >/dev/null; then
  dpkg-query -W -f '${Package}:${Architecture} ${Version} ${Status}\n'
else
  rpm -qa --qf '%{NAME}.%{ARCH} %{VERSION}-%{RELEASE}\n'
fi | sort

section "flatpak remotes"
flatpak remotes --system --columns=name,url 2>/dev/null

section "ufw"
sudo ufw show added 2>/dev/null
